JavaScript is a client-side scripting language used to create dynamic and interactive web pages.

<!DOCTYPE html>
<html>
<body>
  <input type="number" id="num" placeholder="Enter number">
  <button onclick="fact()">Find Factorial</button>
  <p id="result"></p>

  <script>
    function fact() {
      let n = document.getElementById('num').value;
      let f = 1;
      for (let i = 1; i <= n; i++) {
        f *= i;
      }
      document.getElementById('result').innerText = "Factorial = " + f;
    }
  </script>
</body>
</html>
